import sympy as sp; import numpy as np; sqrt15 = sp.sqrt(15); G = (sp.Rational(3,10) - sp.Rational(4,10)*sqrt15, sp.Rational(4,10) + sp.Rational(3,10)*sqrt15); H = ((sp.Rational(15,50) - sp.Rational(36,50)*sqrt15), (sp.Rational(52,10) + sp.Rational(3,10)*sqrt15)); GH_squared = (H[0]-G[0])**2 + (H[1]-G[1])**2; GH_squared_simplified = sp.simplify(GH_squared); GH = sp.sqrt(GH_squared_simplified); GH_simplified = sp.simplify(GH); expected = sp.Rational(32,25)*sqrt15; is_equal = sp.simplify(GH_simplified - expected) == 0; print('VERIFY_PASS' if is_equal else f'VERIFY_FAIL: got {GH_simplified}, expected {expected}')